// Kaleidoscope — mirrored wedge symmetry with slow rotation.
// Segments snaps to 3, 4, 6 or 8 (5 -> 6, 7 -> 8).
uniform float uSegments;  // @param 6 3 8
uniform float uRotSpeed;  // @param 0.08 -1 1
uniform float uZoom;      // @param 2.5 0.5 8
uniform float uFlow;      // @param 0.15 0 1
uniform vec3  uColorA;    // @param #FF6B1A
uniform vec3  uColorB;    // @param #1AB8FF

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);

  int s = int(floor(uSegments + 0.5));
  float n;
  switch (s) {
    case 3: n = 3.0; break;
    case 4: n = 4.0; break;
    case 5:
    case 6: n = 6.0; break;
    case 7:
    case 8: n = 8.0; break;
    default: n = 6.0; break;
  }

  // slow rotation of the whole kaleidoscope
  p = rot(iTime * uRotSpeed) * p;

  float r = length(p);
  float a = atan(p.y, p.x);
  float seg = 6.28318530718 / n;
  a = mod(a, seg);
  a = abs(a - seg * 0.5);           // mirror within wedge
  vec2 q = vec2(cos(a), sin(a)) * r;

  float t = iTime * uFlow;
  vec2 k = q * uZoom;
  float v = fbm(k + vec2(t, -0.7 * t));
  v += 0.5 * fbm(k * 2.3 + v * 1.5 - t * 0.5);
  v /= 1.5;

  float rings = sin(12.0 * r - iTime * 0.6 + v * 7.0) * 0.5 + 0.5;
  float facet = smoothstep(0.02, 0.0, abs(a - seg * 0.5) * r) * 0.25; // soft seam glow

  vec3 col = mix(uColorA, uColorB, smoothstep(0.3, 0.7, v));
  col *= 0.35 + 0.85 * rings;
  col += pow(rings * v, 3.0) * 0.6 + facet;

  float vig = 1.0 - 0.6 * dot(p, p);
  fragColor = vec4(clamp(col * vig, 0.0, 1.0), 1.0);
}
